from jsonb_to_recordset($json$[{"brand_slug":"dermaquest","slug":"3d-stem-cell-hydrating-firming-serum","title_zh_hk":"3D\u5e79\u7d30\u80de\u6c34\u5ae9\u7dca\u808c\u7cbe\u83ef","title_zh_cn":"3D\u5e72\u7ec6\u80de\u6c34\u5ae9\u7d27\u808c\u7cbe\u534e","title_en":"3D Stem Cell Hydrating Firming Serum","description_zh_hk":"<p>\u9069\u5408\u6240\u6709\u808c\u819a<br />\n\u7a81\u7834\u4e00\u822c\u5e79\u7d30\u80de\u7cbe\u83ef\uff0c\u52a0\u5165\u591a\u7a2e\u9ad8\u6fc3\u5ea6\u91ab\u5b78\u690d\u7269\u5e79\u7d30\u80de\uff0c\u9ad8\u6548\u4fee\u5fa9\u808c\u819a\uff0c\u6975\u7dfb\u63d0\u5347\u3001\u518d\u751f\u53ca\u4eae\u767d\u3002\u914d\u5408\u91ab\u5b78\u86cb\u767d\u80bd\u53ca\u900f\u660e\u8cea\u9178\u9209\uff0c\u767c\u63ee\u5f37\u5927\u9396\u6c34\u5ae9\u808c\u529f\u6548\uff0c\u4f7f\u808c\u819a\u6301\u4e45\u6c34\u6f64\u6709\u5149\u6fa4\u3002</p>\n<p>\u4e3b\u8981\u529f\u6548<br />\n\u2013 \u5347\u7d1a\u72483D\u9396\u6c34\u63d0\u5347\u79d1\u6280<br />\n\u2013 \u6536\u7dca\u808c\u819a\u7d44\u7e54\uff0c\u5f9e\u6839\u6e90\u6539\u5584\u76ba\u7d0b\u53ca\u808c\u819a\u7c97\u7cd9\u554f\u984c<br />\n\u2013 \u559a\u9192\u75b2\u5026\u808c\u819a\uff0c\u56de\u5fa9\u6c34\u6f64\u5149\u6fa4\u611f</p>\n<p>\u4e3b\u8981\u6210\u4efd<br />\n\u2013 \u6894\u5b50\u82b1\u5e79\u7d30\u80de<br />\n\u2013 \u7d2b\u9310\u82b1\u5e79\u7d30\u80de<br />\n\u2013 \u7d2b\u4e01\u9999\u5e79\u7d30\u80de<br />\n\u2013 \u900f\u660e\u8cea\u9178\u9209</p>","description_zh_cn":"<p>\u9002\u5408\u6240\u6709\u808c\u80a4<br />\n\u7a81\u7834\u4e00\u822c\u5e72\u7ec6\u80de\u7cbe\u534e\uff0c\u52a0\u5165\u591a\u79cd\u9ad8\u6d53\u5ea6\u533b\u5b66\u690d\u7269\u5e72\u7ec6\u80de\uff0c\u9ad8\u6548\u4fee\u590d\u808c\u80a4\uff0c\u6781\u81f4\u63d0\u5347\u3001\u518d\u751f\u53ca\u4eae\u767d\u3002\u914d\u5408\u533b\u5b66\u86cb\u767d\u80bd\u53ca\u900f\u660e\u8d28\u9178\u94a0\uff0c\u53d1\u6325\u5f3a\u5927\u9501\u6c34\u5ae9\u808c\u529f\u6548\uff0c\u4f7f\u808c\u80a4\u6301\u4e45\u6c34\u6da6\u6709\u5149\u6cfd\u3002</p>\n<p>\u4e3b\u8981\u529f\u6548<b